insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('products','products',true,6291456,array['image/jpeg','image/png','image/webp']),('gallery','gallery',true,6291456,array['image/jpeg','image/png','image/webp']),('branding','branding',true,6291456,array['image/jpeg','image/png','image/webp','image/svg+xml']) on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "public reads camari images" on storage.objects for select using(bucket_id in ('products','gallery','branding'));
create policy "admins upload camari images" on storage.objects for insert to authenticated with check(bucket_id in ('products','gallery','branding') and public.is_admin());
create policy "admins update camari images" on storage.objects for update to authenticated using(bucket_id in ('products','gallery','branding') and public.is_admin()) with check(bucket_id in ('products','gallery','branding') and public.is_admin());
create policy "admins delete camari images" on storage.objects for delete to authenticated using(bucket_id in ('products','gallery','branding') and public.is_admin());
